/* TEN MINUTES — the Vietoris–Rips view of a real GPT-2 sentence.
 *
 * The data is generated by blog/tools/embedding_manifold/embedding_manifold.py.
 * This file is shared by blog/embeddinglab.php and blog/tenminutes/embeddinglab.php.
 */
(function () {
	"use strict";

	function DE() {
		return !!(window.TM && window.TM.lang && window.TM.lang() === "de");
	}

	function css(name, fallback) {
		var value = getComputedStyle(document.documentElement).getPropertyValue(name);
		return value ? value.trim() : fallback;
	}

	function palette() {
		var dark = document.documentElement.getAttribute("data-theme") === "dark" ||
			document.documentElement.classList.contains("dark");
		return {
			dark: dark,
			paper: css("--tm-paper", css("--mn-bg", dark ? "#071a22" : "#ffffff")),
			ink: css("--tm-ink", css("--mn-text", dark ? "#e9f2ee" : "#000000")),
			muted: css("--tm-muted", css("--mn-text-muted", dark ? "#9db5b5" : "#627476")),
			line: css("--tm-line", dark ? "rgba(238,247,244,.18)" : "rgba(0,75,111,.16)"),
			blue: css("--tm-blue", "#1275ac"),
			sky: css("--tm-sky", "#5c9baf"),
			green: css("--tm-green", "#63a44b"),
			lime: css("--tm-lime", "#869b55"),
			gold: css("--tm-gold", "#9f9700"),
			lilac: css("--tm-coral", "#9185be"),
			teal: css("--tm-petrol-mid", "#009299")
		};
	}

	function initCanvas(canvas, draw) {
		if (window.TM && window.TM.initCanvas) {
			var api = window.TM.initCanvas(canvas, draw);
			return api;
		}
		var ctx = canvas.getContext("2d");
		var raf = null;
		var lastW = 0, lastH = 0, lastDpr = 0;
		function paint() {
			raf = null;
			var rect = canvas.getBoundingClientRect();
			if (!rect.width) return;
			var dpr = Math.min(window.devicePixelRatio || 1, 2);
			if (rect.width !== lastW || rect.height !== lastH || dpr !== lastDpr) {
				canvas.width = Math.round(rect.width * dpr);
				canvas.height = Math.round(rect.height * dpr);
				lastW = rect.width;
				lastH = rect.height;
				lastDpr = dpr;
			}
			ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
			draw(ctx, rect.width, rect.height);
		}
		function request() {
			if (raf === null) raf = requestAnimationFrame(paint);
		}
		if (window.ResizeObserver) new ResizeObserver(request).observe(canvas);
		else window.addEventListener("resize", request);
		request();
		return { redraw: request, ctx: ctx };
	}

	function norm(value) {
		return String(value == null ? "" : value).replace(/\s+/g, " ").trim();
	}

	function dist3(a, b) {
		var dx = a[0] - b[0], dy = a[1] - b[1], dz = a[2] - b[2];
		return Math.sqrt(dx * dx + dy * dy + dz * dz);
	}

	function centerScale(points) {
		var n = points.length;
		var cx = 0, cy = 0, cz = 0;
		points.forEach(function (p) { cx += p[0]; cy += p[1]; cz += p[2]; });
		cx /= n; cy /= n; cz /= n;
		var max = 0.0001;
		var centered = points.map(function (p) {
			var q = [p[0] - cx, p[1] - cy, p[2] - cz];
			max = Math.max(max, Math.hypot(q[0], q[1], q[2]));
			return q;
		});
		return centered.map(function (q) { return [q[0] / max, q[1] / max, q[2] / max]; });
	}

	function graph(points, epsilon) {
		var n = points.length;
		var edges = [];
		var adjacent = [];
		var parent = [];
		for (var i = 0; i < n; i++) {
			adjacent.push([]);
			parent.push(i);
		}
		function find(x) {
			while (parent[x] !== x) {
				parent[x] = parent[parent[x]];
				x = parent[x];
			}
			return x;
		}
		for (var a = 0; a < n; a++) {
			for (var b = a + 1; b < n; b++) {
				if (dist3(points[a], points[b]) <= epsilon) {
					edges.push([a, b]);
					adjacent[a].push(b);
					adjacent[b].push(a);
					var ra = find(a), rb = find(b);
					if (ra !== rb) parent[ra] = rb;
				}
			}
		}
		var components = 0;
		for (var c = 0; c < n; c++) if (find(c) === c) components++;
		var triangles = [];
		for (var i2 = 0; i2 < n; i2++) {
			for (var j2 = i2 + 1; j2 < n; j2++) {
				if (adjacent[i2].indexOf(j2) === -1) continue;
				for (var k2 = j2 + 1; k2 < n; k2++) {
					if (adjacent[i2].indexOf(k2) !== -1 && adjacent[j2].indexOf(k2) !== -1) {
						triangles.push([i2, j2, k2]);
					}
				}
			}
		}
		return {
			edges: edges,
			triangles: triangles,
			adjacent: adjacent,
			components: components,
			cycles: edges.length - n + components
		};
	}

	function shortestLoop(complex) {
		var best = null;
		complex.edges.forEach(function (edge) {
			var start = edge[0], goal = edge[1];
			var queue = [start];
			var previous = {};
			previous[start] = -1;
			while (queue.length) {
				var node = queue.shift();
				for (var i = 0; i < complex.adjacent[node].length; i++) {
					var next = complex.adjacent[node][i];
					if (node === start && next === goal) continue;
					if (previous[next] !== undefined) continue;
					previous[next] = node;
					queue.push(next);
				}
			}
			if (previous[goal] === undefined) return;
			var path = [goal];
			var walk = goal;
			while (walk !== start) {
				walk = previous[walk];
				if (walk === undefined || path.length > 80) return;
				path.push(walk);
			}
			if (!best || path.length < best.length) best = path;
		});
		return best;
	}

	function nearestScan(scan, epsilon) {
		var best = scan[0];
		for (var i = 1; i < scan.length; i++) {
			if (Math.abs(scan[i].eps - epsilon) < Math.abs(best.eps - epsilon)) best = scan[i];
		}
		return best;
	}

	function labelFor(token, index, de) {
		var text = de ? token.display : token.display;
		return text + (token.position != null ? " (" + (token.position + 1) + ")" : "");
	}

	window.EmbeddingManifold = {
		render: function (hostId, options) {
			var host = document.getElementById(hostId);
			var data = window.TM_EMBEDDING_MANIFOLD;
			if (!host || !data) return null;
			var opts = options || {};
			var de = DE();
			var mode = opts.mode === "token" ? "token" : "combined";
			var state = {
				mode: mode,
				epsilon: data.modes[mode].epsilon.suggested.eps,
				fill: opts.fill !== false,
				order: true,
				rotX: -0.35,
				rotY: 0.65,
				zoom: 1,
				drag: null,
				hover: -1,
				loop: null,
				points: [],
				complex: null,
				api: null
			};

			host.innerHTML = "";
			host.style.position = "relative";
			var canvas = document.createElement("canvas");
			canvas.className = "em-canvas";
			canvas.setAttribute("tabindex", "0");
			canvas.setAttribute("role", "img");
			canvas.setAttribute("aria-label", de
				? "Dreidimensionaler Vietoris-Rips-Komplex der GPT-2-Token-Embeddings"
				: "Three-dimensional Vietoris–Rips complex of the GPT-2 token embeddings");
			host.appendChild(canvas);

			var bar = document.createElement("div");
			bar.className = "em-controls";
			host.appendChild(bar);

			function button(label, onClick, active) {
				var b = document.createElement("button");
				b.type = "button";
				b.className = "em-btn" + (active ? " is-on" : "");
				b.textContent = label;
				b.addEventListener("click", onClick);
				bar.appendChild(b);
				return b;
			}

			var modeCombined = button(de ? "Token + Position" : "Token + Position", function () {
				setMode("combined");
			}, state.mode === "combined");
			var modeToken = button(de ? "Nur Token" : "Token only", function () {
				setMode("token");
			}, state.mode === "token");

			var sliderWrap = document.createElement("label");
			sliderWrap.className = "em-slider";
			var sliderLabel = document.createElement("span");
			sliderLabel.textContent = de ? "Epsilon" : "Epsilon";
			var slider = document.createElement("input");
			slider.type = "range";
			slider.min = "0";
			slider.max = "100";
			slider.step = "1";
			var sliderOut = document.createElement("output");
			sliderOut.className = "em-epsilon";
			sliderWrap.appendChild(sliderLabel);
			sliderWrap.appendChild(slider);
			sliderWrap.appendChild(sliderOut);
			bar.appendChild(sliderWrap);

			var fillBtn = button(de ? "Dreiecke füllen" : "Fill triangles", function () {
				state.fill = !state.fill;
				fillBtn.classList.toggle("is-on", state.fill);
				redraw();
			}, state.fill);
			var orderBtn = button(de ? "Satzreihenfolge" : "Sentence order", function () {
				state.order = !state.order;
				orderBtn.classList.toggle("is-on", state.order);
				redraw();
			}, state.order);
			var loopBtn = button(de ? "Schleife zeigen" : "Show a loop", function () {
				if (!state.complex) return;
				state.loop = state.loop ? null : shortestLoop(state.complex);
				loopBtn.classList.toggle("is-on", !!state.loop);
				redraw();
			}, false);
			var resetBtn = button(de ? "Ansicht zurücksetzen" : "Reset view", function () {
				state.rotX = -0.35;
				state.rotY = 0.65;
				state.zoom = 1;
				state.loop = null;
				loopBtn.classList.remove("is-on");
				redraw();
			}, false);

			var readout = document.createElement("p");
			readout.className = "em-readout";
			host.appendChild(readout);

			var hint = document.createElement("p");
			hint.className = "em-hint";
			hint.textContent = de
				? "Ziehe zum Drehen, scrolle zum Zoomen. Die Punkte sind echte GPT-2-Token-Embeddings plus Positionsvektoren; die 3D-Lage ist eine PCA-Projektion."
				: "Drag to rotate, scroll to zoom. The points are real GPT-2 token embeddings plus position vectors; the 3D layout is a PCA projection.";
			host.appendChild(hint);

			function setMode(next) {
				state.mode = next;
				modeCombined.classList.toggle("is-on", next === "combined");
				modeToken.classList.toggle("is-on", next === "token");
				var scan = data.modes[next].epsilon;
				state.epsilon = scan.suggested.eps;
				state.loop = null;
				loopBtn.classList.remove("is-on");
				setup();
				redraw();
			}

			function setup() {
				var payload = data.modes[state.mode];
				state.points = centerScale(payload.coords);
				var grid = payload.epsilon.grid;
				var lo = grid[0].eps, hi = grid[grid.length - 1].eps;
				slider.min = String(lo);
				slider.max = String(hi);
				slider.step = String((hi - lo) / 200 || 0.01);
				slider.value = String(state.epsilon);
				state.complex = graph(state.points, state.epsilon);
				updateReadout();
			}

			function updateReadout() {
				var scan = nearestScan(data.modes[state.mode].epsilon.grid, state.epsilon);
				var complex = state.complex;
				var parts = [];
				parts.push((de ? "Komponenten " : "Components ") + complex.components);
				parts.push((de ? "Kanten " : "Edges ") + complex.edges.length);
				parts.push((de ? "Dreiecke " : "Triangles ") + complex.triangles.length);
				parts.push((de ? "Schleifen " : "1-skeleton loops ") + complex.cycles);
				if (scan) parts.push((de ? "gefüllt B₁ " : "filled B₁ ") + scan.b1);
				sliderOut.textContent = state.epsilon.toFixed(2);
				readout.textContent = parts.join(" · ");
			}

			function rotatePoint(p) {
				var cy = Math.cos(state.rotY), sy = Math.sin(state.rotY);
				var cx = Math.cos(state.rotX), sx = Math.sin(state.rotX);
				var x1 = p[0] * cy + p[2] * sy;
				var z1 = -p[0] * sy + p[2] * cy;
				var y1 = p[1] * cx - z1 * sx;
				var z2 = p[1] * sx + z1 * cx;
				return [x1, y1, z2];
			}

			function project(p, w, h) {
				var q = rotatePoint(p);
				var scale = Math.min(w, h) * 0.72 * state.zoom;
				var perspective = 3.4;
				var factor = perspective / (perspective + q[2]);
				return {
					x: w / 2 + q[0] * scale * factor,
					y: h / 2 - q[1] * scale * factor,
					z: q[2],
					s: factor
				};
			}

			function colorFor(index) {
				var c = palette();
				var stops = [c.blue, c.sky, c.green, c.lime, c.gold, c.lilac];
				var t = index / Math.max(1, data.tokens.length - 1) * (stops.length - 1);
				var i = Math.floor(t);
				var f = t - i;
				function hex(v) {
					v = v.replace("#", "");
					if (v.length === 3) v = v[0] + v[0] + v[1] + v[1] + v[2] + v[2];
					return [parseInt(v.slice(0, 2), 16), parseInt(v.slice(2, 4), 16), parseInt(v.slice(4, 6), 16)];
				}
				var a = hex(stops[i]);
				var b = hex(stops[Math.min(stops.length - 1, i + 1)]);
				return "rgb(" + Math.round(a[0] + (b[0] - a[0]) * f) + "," +
					Math.round(a[1] + (b[1] - a[1]) * f) + "," +
					Math.round(a[2] + (b[2] - a[2]) * f) + ")";
			}

			function catmull(p0, p1, p2, p3, t) {
				var t2 = t * t, t3 = t2 * t;
				return [
					0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
					0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3),
					0.5 * ((2 * p1[2]) + (-p0[2] + p2[2]) * t + (2 * p0[2] - 5 * p1[2] + 4 * p2[2] - p3[2]) * t2 + (-p0[2] + 3 * p1[2] - 3 * p2[2] + p3[2]) * t3)
				];
			}

			function draw(ctx, w, h) {
				var c = palette();
				ctx.clearRect(0, 0, w, h);
				if (!state.points.length) return;

				var projected = state.points.map(function (p) { return project(p, w, h); });
				var complex = state.complex;

				if (state.fill) {
					var tris = complex.triangles.map(function (tri) {
						return {
							tri: tri,
							z: (projected[tri[0]].z + projected[tri[1]].z + projected[tri[2]].z) / 3
						};
					}).sort(function (a, b) { return b.z - a.z; });
					tris.forEach(function (item) {
						var tri = item.tri;
						ctx.beginPath();
						ctx.moveTo(projected[tri[0]].x, projected[tri[0]].y);
						ctx.lineTo(projected[tri[1]].x, projected[tri[1]].y);
						ctx.lineTo(projected[tri[2]].x, projected[tri[2]].y);
						ctx.closePath();
						ctx.fillStyle = c.dark ? "rgba(92,155,175,.075)" : "rgba(18,117,172,.06)";
						ctx.fill();
					});
				}

				var edgeAlpha = c.dark ? 0.25 : 0.17;
				complex.edges.forEach(function (edge) {
					var a = projected[edge[0]], b = projected[edge[1]];
					ctx.beginPath();
					ctx.moveTo(a.x, a.y);
					ctx.lineTo(b.x, b.y);
					ctx.strokeStyle = c.dark ? "rgba(157,181,181,.28)" : "rgba(0,75,111,.18)";
					ctx.globalAlpha = edgeAlpha + 0.12 * Math.min(a.s, b.s);
					ctx.lineWidth = 1;
					ctx.stroke();
				});
				ctx.globalAlpha = 1;

				if (state.order) {
					var points = projected;
					ctx.lineWidth = 2.2;
					for (var i = 0; i + 1 < points.length; i++) {
						var p0 = points[Math.max(0, i - 1)];
						var p1 = points[i];
						var p2 = points[i + 1];
						var p3 = points[Math.min(points.length - 1, i + 2)];
						ctx.beginPath();
						ctx.moveTo(p1.x, p1.y);
						for (var t = 1; t <= 8; t++) {
							var q = catmull(p0, p1, p2, p3, t / 8);
							var pr = project(q, w, h);
							ctx.lineTo(pr.x, pr.y);
						}
						ctx.strokeStyle = colorFor(i);
						ctx.globalAlpha = 0.55;
						ctx.stroke();
					}
					ctx.globalAlpha = 1;
				}

				if (state.loop && state.loop.length > 1) {
					ctx.beginPath();
					state.loop.forEach(function (idx, k) {
						var p = projected[idx];
						if (k === 0) ctx.moveTo(p.x, p.y);
						else ctx.lineTo(p.x, p.y);
					});
					ctx.closePath();
					ctx.strokeStyle = c.gold;
					ctx.lineWidth = 3;
					ctx.globalAlpha = 0.95;
					ctx.stroke();
					ctx.globalAlpha = 1;
				}

				var order = projected.map(function (p, i) { return i; });
				order.sort(function (a, b) { return projected[b].z - projected[a].z; });
				order.forEach(function (idx) {
					var p = projected[idx];
					var token = data.tokens[idx];
					var r = (idx === state.hover ? 7 : 4.6) * Math.min(1.25, p.s);
					var col = colorFor(idx);
					ctx.beginPath();
					ctx.arc(p.x, p.y, r + 4, 0, Math.PI * 2);
					ctx.fillStyle = col;
					ctx.globalAlpha = 0.14;
					ctx.fill();
					ctx.globalAlpha = 1;
					ctx.beginPath();
					ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
					ctx.fillStyle = col;
					ctx.fill();
					ctx.lineWidth = 1.4;
					ctx.strokeStyle = c.paper;
					ctx.stroke();
				});

				order.forEach(function (idx) {
					var p = projected[idx];
					var token = data.tokens[idx];
					var label = labelFor(token, idx, de);
					ctx.font = "600 " + (idx === state.hover ? 12 : 10) + "px Barlow, system-ui, sans-serif";
					ctx.textAlign = "center";
					ctx.textBaseline = "middle";
					var tw = ctx.measureText(label).width;
					ctx.globalAlpha = idx === state.hover ? 1 : 0.92;
					ctx.fillStyle = c.paper;
					ctx.fillRect(p.x - tw / 2 - 4, p.y - 22, tw + 8, 15);
					ctx.globalAlpha = 1;
					ctx.fillStyle = idx === state.hover ? c.ink : c.muted;
					ctx.fillText(label, p.x, p.y - 15);
				});

				if (state.loop && state.loop.length) {
					var center = state.loop.reduce(function (acc, idx) {
						acc.x += projected[idx].x / state.loop.length;
						acc.y += projected[idx].y / state.loop.length;
						return acc;
					}, { x: 0, y: 0 });
					ctx.font = "700 10px Barlow, system-ui, sans-serif";
					ctx.textAlign = "center";
					ctx.fillStyle = c.gold;
					ctx.fillText(de ? "Schleife" : "loop", center.x, center.y);
				}

				if (state.hover >= 0) {
					var hovered = projected[state.hover];
					var token = data.tokens[state.hover];
					var info = (de ? "Token " : "Token ") + norm(token.display) +
						" · " + (de ? "Position " : "position ") + (token.position + 1) +
						" · id " + token.id;
					ctx.font = "600 10px Barlow, system-ui, sans-serif";
					ctx.textAlign = "left";
					ctx.fillStyle = c.muted;
					ctx.fillText(info, 12, h - 12);
				}
				if (state.loop && state.loop.length > 1) {
					var loopInfo = de ? "Goldene Linie: eine Schleife in der 1-Skelett-Graph" : "Gold line: one loop in the 1-skeleton graph";
					ctx.font = "600 10px Barlow, system-ui, sans-serif";
					ctx.textAlign = "right";
					ctx.fillStyle = c.gold;
					ctx.fillText(loopInfo, w - 12, h - 12);
				}
			}

			function redraw() {
				if (state.api) state.api.redraw();
			}

			canvas.addEventListener("pointerdown", function (event) {
				state.drag = { x: event.clientX, y: event.clientY, rotX: state.rotX, rotY: state.rotY };
				canvas.setPointerCapture(event.pointerId);
				canvas.style.cursor = "grabbing";
			});
			canvas.addEventListener("pointermove", function (event) {
				if (state.drag) {
					state.rotY = state.drag.rotY + (event.clientX - state.drag.x) * 0.008;
					state.rotX = state.drag.rotX + (event.clientY - state.drag.y) * 0.008;
					redraw();
					return;
				}
				var rect = canvas.getBoundingClientRect();
				var x = event.clientX - rect.left;
				var y = event.clientY - rect.top;
				var best = -1, bestDist = 22;
				state.points.forEach(function (p, idx) {
					var pr = project(p, rect.width, rect.height);
					var d = Math.hypot(pr.x - x, pr.y - y);
					if (d < bestDist) { bestDist = d; best = idx; }
				});
				if (best !== state.hover) { state.hover = best; redraw(); }
			});
			canvas.addEventListener("pointerup", function () {
				state.drag = null;
				canvas.style.cursor = "grab";
			});
			canvas.addEventListener("pointercancel", function () {
				state.drag = null;
				canvas.style.cursor = "grab";
			});
			canvas.addEventListener("pointerleave", function () {
				state.hover = -1;
				redraw();
			});
			canvas.addEventListener("wheel", function (event) {
				event.preventDefault();
				state.zoom = Math.max(0.45, Math.min(2.8, state.zoom * (event.deltaY > 0 ? 0.92 : 1.08)));
				redraw();
			}, { passive: false });
			canvas.addEventListener("keydown", function (event) {
				var handled = true;
				if (event.key === "ArrowLeft") state.rotY -= 0.08;
				else if (event.key === "ArrowRight") state.rotY += 0.08;
				else if (event.key === "ArrowUp") state.rotX += 0.08;
				else if (event.key === "ArrowDown") state.rotX -= 0.08;
				else if (event.key === "+" || event.key === "=") state.zoom = Math.min(2.8, state.zoom * 1.08);
				else if (event.key === "-") state.zoom = Math.max(0.45, state.zoom / 1.08);
				else handled = false;
				if (handled) { event.preventDefault(); redraw(); }
			});
			canvas.style.cursor = "grab";

			slider.addEventListener("input", function () {
				state.epsilon = parseFloat(slider.value);
				state.complex = graph(state.points, state.epsilon);
				state.loop = null;
				loopBtn.classList.remove("is-on");
				updateReadout();
				redraw();
			});

			setup();
			state.api = initCanvas(canvas, draw);
			host.setAttribute("data-demo-ready", "1");
			var redrawTheme = function () {
				state.api.redraw();
			};
			window.addEventListener("tm:theme", redrawTheme);
			if (window.__MN_DARK && window.__MN_DARK.onChange) window.__MN_DARK.onChange(redrawTheme);
			return {
				setMode: setMode,
				redraw: redraw
			};
		}
	};

	if (document.currentScript) {
		document.currentScript.setAttribute("data-embedding-manifold", "1");
	}
})();
